const payload = $input.first().json.body || $input.first().json;

if (!payload.session_token) {
  throw new Error('Missing session_token in click log');
}

return [{
  json: {
    session_token: payload.session_token,
    fbclid: payload.fbclid || '',
    fbclid_ts: payload.fbclid_ts || '',
    utm_source: payload.utm_source || '',
    utm_medium: payload.utm_medium || '',
    utm_campaign: payload.utm_campaign || '',
    utm_content: payload.utm_content || '',
    channel: payload.channel || 'WhatsApp',
    brand: payload.brand || 'Home Cartel',
    timestamp: payload.timestamp || new Date().toISOString()
  }
}];

const clickData = $('Normalize & Validate Payload').first().json;
const searchResults = $input.first().json.results || [];

// Match heuristics based on channel and brand
let matchedTicket = null;
for (const t of searchResults) {
  const channel = (t.via && t.via.channel) ? t.via.channel.toLowerCase() : '';
  if (clickData.channel.toLowerCase().includes('whatsapp') && channel.includes('whatsapp')) {
    matchedTicket = t;
    break;
  } else if (clickData.channel.toLowerCase().includes('messenger') && (channel.includes('facebook') || channel.includes('messenger'))) {
    matchedTicket = t;
    break;
  } else if (clickData.channel.toLowerCase().includes('viber') && channel.includes('viber')) {
    matchedTicket = t;
    break;
  }
}

if (matchedTicket) {
  return [{
    json: {
      matched: true,
      ticket_id: matchedTicket.id,
      session_token: clickData.session_token,
      fbclid: clickData.fbclid,
      utm_source: clickData.utm_source,
      utm_campaign: clickData.utm_campaign,
      channel: clickData.channel,
      brand: clickData.brand,
      confidence: 'high_channel_match'
    }
  }];
} else {
  return [{
    json: {
      matched: false,
      pending_key: 'pending_click_' + clickData.session_token,
      clickData: clickData
    }
  }];
}

// Store in n8n Static Data / Pending Store with 24h TTL
const pendingKey = $json.pending_key;
const payload = $json.clickData;
// In n8n, this is persisted to workflow static data or external Redis/DB store
return [{
  json: {
    status: 'stored_in_pending_pool',
    key: pendingKey,
    expires_in_hours: 24,
    payload: payload
  }
}];
